 "content": "def transform(grid):
    """Complete the partial row matching the solid marker row with color 1."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    solid_markers = {
        row[0]
        for row in grid
        if all(value == row[0] for value in row) and row[0] != background
    }
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        present = [value for value in row if value in solid_markers]
        if present and any(value == background for value in row):
            marker = present[0]
            if all(value in (marker, background) for value in row):
                out[r] = [marker if value == marker else 1 for value in row]
    return out
